  part def Controller {
    in attribute io_4 : Real;
    attribute channelIndex : Integer := 0;
    perform action tick {
      first start;
      then assign channelIndex := (if channelIndex == 4 ? 0 else channelIndex + 1);
    }
    out attribute io_0 : Boolean = (channelIndex == 1) or (channelIndex == 3) or (channelIndex == 5) or (channelIndex == 7) or (channelIndex == 9) or (channelIndex == 11) or (channelIndex == 13) or (channelIndex == 15);
    out attribute io_1 : Boolean = (channelIndex == 2) or (channelIndex == 3) or (channelIndex == 6) or (channelIndex == 7) or (channelIndex == 10) or (channelIndex == 11) or (channelIndex == 14) or (channelIndex == 15);
    out attribute io_2 : Boolean = (channelIndex >= 4) and (channelIndex <= 7) or (channelIndex >= 12) and (channelIndex <= 15);
    out attribute io_3 : Boolean = false;
    out attribute serial_0_trigger : Boolean = channelIndex == 0;
    out attribute serial_0_value_0 : Integer = RealFunctions::floor(io_4);
    out attribute serial_0_value_1 : Integer = RealFunctions::floor(io_4);
    out attribute serial_0_value_2 : Integer = RealFunctions::floor(io_4);
    out attribute serial_0_value_3 : Integer = RealFunctions::floor(io_4);
    out attribute serial_0_value_4 : Integer = RealFunctions::floor(io_4);
  }
  part system : Controller;
